#include <vector>
#include <iostream>

void bulk_insert_optimized(const std::vector<int>& source) {
    std::vector<int> target;
    // Optimize: Prevent repeated reallocations
    target.reserve(source.size()); 

    for (int val : source) {
        target.push_back(val);
    }
    // target capacity is size, only one allocation occurred.
}
